#[test]
fn divide_signatures() {
    let mut failures = Vec::new();
    {
        let a: Matrix<f64> = Matrix::from_column_major(2, 2, vec![0.309, 0.318, 0.327, 0.336]);
        let b: f64 = 0.721;
        let got = un(&a, &mut |a| eval(divide(a as f64, b as f64)));
        let want: Vec<f64> = items(&a)
            .into_iter()
            .map(|a| (a, b))
            .map(|(a, b)| eval(divide(a as f64, b as f64)))
            .collect();
        assert!(!want.is_empty());
        compare("divide(Matrix<f64>, f64)", items(&got), want, &mut failures);
    }
    {
        let a: Vec<f64> = vec![0.309, 0.318];
        let b: f64 = 0.721;
        let got = un(&a, &mut |a| eval(divide(a as f64, b as f64)));
        let want: Vec<f64> = items(&a)
            .into_iter()
            .map(|a| (a, b))
            .map(|(a, b)| eval(divide(a as f64, b as f64)))
            .collect();
        assert!(!want.is_empty());
        compare("divide(Vec<f64>, f64)", items(&got), want, &mut failures);
    }
    {
        let a: f64 = 0.309;
        let b: Matrix<f64> = Matrix::from_column_major(2, 2, vec![0.721, 0.742, 0.763, 0.784]);
        let got = un(&b, &mut |b| eval(divide(a as f64, b as f64)));
        let want: Vec<f64> = items(&b)
            .into_iter()
            .map(|b| (a, b))
            .map(|(a, b)| eval(divide(a as f64, b as f64)))
            .collect();
        assert!(!want.is_empty());
        compare("divide(f64, Matrix<f64>)", items(&got), want, &mut failures);
    }
    {
        let a: f64 = 0.309;
        let b: Vec<f64> = vec![0.721, 0.742];
        let got = un(&b, &mut |b| eval(divide(a as f64, b as f64)));
        let want: Vec<f64> = items(&b)
            .into_iter()
            .map(|b| (a, b))
            .map(|(a, b)| eval(divide(a as f64, b as f64)))
            .collect();
        assert!(!want.is_empty());
        compare("divide(f64, Vec<f64>)", items(&got), want, &mut failures);
    }
    assert!(failures.is_empty(), "\n{}", failures.join("\n"));
}

