#[test]
fn exponential_cdf_signatures() {
    let mut failures = Vec::new();
    {
        let a: Vec<f64> = vec![0.309, 0.318];
        let b: Vec<f64> = vec![0.721, 0.742];
        let got = bin(&a, &b, &mut |a, b| {
            eval(exponential_cdf(a as f64, b as f64))
        })
        .unwrap();
        let want: Vec<f64> = items(&a)
            .into_iter()
            .zip(items(&b))
            .map(|(a, b)| eval(exponential_cdf(a as f64, b as f64)))
            .collect();
        assert!(!want.is_empty());
        compare(
            "exponential_cdf(Vec<f64>, Vec<f64>)",
            items(&got),
            want,
            &mut failures,
        );
    }
    {
        let a: Vec<f64> = vec![0.309, 0.318];
        let b: f64 = 0.721;
        let got = un(&a, &mut |a| eval(exponential_cdf(a as f64, b as f64)));
        let want: Vec<f64> = items(&a)
            .into_iter()
            .map(|a| (a, b))
            .map(|(a, b)| eval(exponential_cdf(a as f64, b as f64)))
            .collect();
        assert!(!want.is_empty());
        compare(
            "exponential_cdf(Vec<f64>, f64)",
            items(&got),
            want,
            &mut failures,
        );
    }
    {
        let a: f64 = 0.309;
        let b: Vec<f64> = vec![0.721, 0.742];
        let got = un(&b, &mut |b| eval(exponential_cdf(a as f64, b as f64)));
        let want: Vec<f64> = items(&b)
            .into_iter()
            .map(|b| (a, b))
            .map(|(a, b)| eval(exponential_cdf(a as f64, b as f64)))
            .collect();
        assert!(!want.is_empty());
        compare(
            "exponential_cdf(f64, Vec<f64>)",
            items(&got),
            want,
            &mut failures,
        );
    }
    assert!(failures.is_empty(), "\n{}", failures.join("\n"));
}

