#[test]
fn plus_signatures() {
    let mut failures = Vec::new();
    {
        let x: Matrix<f64> = Matrix::from_column_major(2, 2, vec![0.309, 0.318, 0.327, 0.336]);
        let got = un(&x, &mut |v| eval(plus(v as f64)));
        let want: Vec<f64> = items(&x)
            .into_iter()
            .map(|v| eval(plus(v as f64)))
            .collect();
        compare("plus(Matrix<f64>)", items(&got), want, &mut failures);
    }
    {
        let x: Vec<f64> = vec![0.309, 0.318];
        let got = un(&x, &mut |v| eval(plus(v as f64)));
        let want: Vec<f64> = items(&x)
            .into_iter()
            .map(|v| eval(plus(v as f64)))
            .collect();
        compare("plus(Vec<f64>)", items(&got), want, &mut failures);
    }
    assert!(failures.is_empty(), "\n{}", failures.join("\n"));
}

